// SPDX-License-Identifier: GPL-2.0-or-later
//! Standalone boot of the FMV console test: run it once and leave the
//! summary up until reset.
#![no_std]
#![no_main]

extern crate psx_rt;

use psx_rt::interrupts;

#[no_mangle]
fn main() {
    interrupts::install_vblank_counter();
    let _ = hello_fmv::run();
    loop {
        interrupts::wait_vblank();
    }
}

//! `hello-fmv` -- FMV console test: stream a 2x STR with XA audio, check
//! every sector, and show the counts over the video.
//!
//! The disc carries `MOVIE.STR`, built by `cargo run -p xtask -- fmv-test-movie` from
//! synthetic content only: a 320x240 15 fps test pattern with temporal
//! noise (so every frame fills the 2x sector budget) and interleaved XA
//! stereo beeps, one per second. Each video sector carries its ordinal,
//! the file's video-sector total, its index in the file and a checksum
//! (see tools/xtask), so the player can tell a skipped sector (LOST) from a
//! corrupt one (BAD) while the drive streams for 75 seconds.
//!
//! Pipeline per frame:
//!
//! 1. The drive streams at double speed with XA-ADPCM on and the file 1 /
//!    channel 0 filter set: audio sectors go straight to the SPU, video
//!    sectors arrive as 2048-byte data. A polled pump drains every ready
//!    sector (checksum, ordinal gap check) into a three-slot frame ring
//!    and runs between every unit of work, including every wait.
//! 2. `psx_fmv::bitstream::decode_frame` runs the bitstream decode on the CPU.
//! 3. The MDEC decodes at 15bpp (DMA0 in); each 16-pixel column comes back
//!    over DMA1 and goes to the back buffer.
//! 4. The overlay is drawn over the frame, then the display flips at a
//!    VBlank, paced to 15 fps.
//!
//! A frame completed while an older one is still queued replaces it (LATE:
//! the decoder is slower than the stream, which costs smoothness, not
//! data). When the stream ends a summary screen stays up. The same numbers
//! go to the TTY as one `FMV PASS ...` / `FMV FAIL ...` line.
//!
//! [`run`] is the whole test and returns once the summary is on screen, so
//! the same player runs from this example's own boot (`src/bin.rs`) and from
//! the hardware-test suite's menu. The caller owns the VBlank counter: it
//! must already be installed, because reinstalling it would reset a count
//! the caller may be pacing on.

#![no_std]

use core::ptr::addr_of_mut;
use psx_fmv::{bitstream, iso, mdec::Mdec, rle::RleBuffer, stream::FrameAssembler};
use psx_font::{
    fonts::{basic::BASIC, basic_8x16::BASIC_8X16_BITMAP},
    BitOrder, BitmapFont, FontAtlas,
};
use psx_gpu::display::{DisplayConfig, Resolution, VideoMode};
use psx_gpu::prim::FillRect;
use psx_gpu::Gpu;
use psx_io::periph::{Cd, MdecDma};
use psx_pack::cd::{SectorReader, SECTOR_WORDS};
use psx_rt::{interrupts, tty, Peripherals};
use psx_spu::{self as spu, CdVolume, Spu, Volume};
use psx_vram::{Clut, TextureDepth, TexturePage, VramRect};

const MOVIE: &str = "MOVIE.STR";
/// Double speed, XA-ADPCM to the SPU, file/channel filter.
const CD_MODE: u8 = 0x80 | 0x40 | 0x08;
const XA_FILE: u8 = 1;
const XA_CHANNEL: u8 = 0;

const WIDTH: u16 = 320;
const HEIGHT: u16 = 240;
const COLUMNS: u16 = WIDTH / 16;
const ROWS: u32 = HEIGHT as u32 / 16;
/// 15bpp column of 16 x HEIGHT pixels, two per word.
const COLUMN_WORDS: usize = 8 * HEIGHT as usize;
/// VBlanks per movie frame: 60 Hz / 15 fps.
const VBLANKS_PER_FRAME: u32 = 4;
/// Frame slot: 16 chunks of 2016 bytes (a 2x 15 fps frame is 8 to 10).
const SLOT_WORDS: usize = 16 * 2016 / 4;
const SLOTS: usize = 3;
/// MDEC run-length buffer: 64K halfwords.
const RLE_WORDS: usize = 32 * 1024;
/// End the stream if no sector arrives for this long (2 s).
pub const STALL_VBLANKS: u32 = 120;
/// Checksum seed; must match tools/xtask/src/fmv_movie.rs.
const SEED: u32 = 0x9E37_79B9;
/// First word of every STR video sector: 0x0160, 0x8001.
const STR_MAGIC: u32 = 0x8001_0160;

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);
const SMALL_TPAGE: TexturePage = TexturePage::new(384, 0, TextureDepth::Bit4);
const SMALL_CLUT: Clut = Clut::new(336, 256);
/// Left margin: keeps text inside a CRT's overscan-safe area.
const X0: i16 = 16;

/// The 8x16 VGA font with every column doubled: 16x16 glyphs that the
/// 1:1 textured-rectangle path draws exactly, big enough to read on a
/// filmed TV. (Scaled quads interpolate UVs; a rect blit cannot bleed.)
static WIDE_BITMAP: [u8; 128 * 16 * 2] = widen(&BASIC_8X16_BITMAP);
static WIDE: BitmapFont = BitmapFont {
    glyph_w: 16,
    glyph_h: 16,
    first_char: 0,
    glyph_count: 128,
    bitmap: &WIDE_BITMAP,
    glyph_advances: None,
    advance_x: 16,
    line_height: 16,
    bit_order: BitOrder::Msb,
};

const fn widen(src: &[u8; 2048]) -> [u8; 4096] {
    let mut out = [0u8; 4096];
    let mut i = 0;
    while i < 2048 {
        let b = src[i];
        let mut w: u16 = 0;
        let mut bit = 0;
        while bit < 8 {
            if b & (0x80 >> bit) != 0 {
                w |= 0xC000 >> (2 * bit);
            }
            bit += 1;
        }
        out[2 * i] = (w >> 8) as u8;
        out[2 * i + 1] = w as u8;
        i += 1;
    }
    out
}
const WHITE: (u8, u8, u8) = (220, 220, 220);
const GREEN: (u8, u8, u8) = (60, 220, 90);
const RED: (u8, u8, u8) = (240, 60, 60);
const YELLOW: (u8, u8, u8) = (230, 210, 60);

// The devices this test drives, owned for the length of a run: the drive's
// sector reader (which holds the CD token) and the MDEC driver (which holds
// its DMA token). Built by `install_devices` at each entry point, in separate
// statics so a reference to one never aliases a reference to the other.
static mut READER: Option<SectorReader> = None;
static mut MDEC: Option<Mdec> = None;
static mut SECTOR: [u32; SECTOR_WORDS] = [0; SECTOR_WORDS];
static mut SLOT: [[u32; SLOT_WORDS]; SLOTS] = [[0; SLOT_WORDS]; SLOTS];
static mut RLE: RleBuffer<RLE_WORDS> = RleBuffer::new();
static mut COLUMN: [u32; COLUMN_WORDS] = [0; COLUMN_WORDS];

/// Where the CPU time goes, sampled from root counter 2 (system clock / 8)
/// at every pump and phase change. Each interval stays under the counter's
/// 65536 * 8-cycle wrap because the pump runs at least once per column.
const PHASE_VLC: usize = 0;
const PHASE_MDEC: usize = 1;
const PHASE_WAIT: usize = 2;
static mut PHASE: usize = PHASE_WAIT;
static mut LAST: u16 = 0;
static mut ACC: [u32; 3] = [0; 3];

fn clock(next: Option<usize>) {
    use psx_io::timers::{counter, Timer};
    // SAFETY: single-threaded profiling statics.
    unsafe {
        let now = counter(Timer::Timer2);
        let phase = *addr_of_mut!(PHASE);
        (*addr_of_mut!(ACC))[phase] += now.wrapping_sub(*addr_of_mut!(LAST)) as u32;
        *addr_of_mut!(LAST) = now;
        if let Some(n) = next {
            *addr_of_mut!(PHASE) = n;
        }
    }
}

/// Stream state the pump owns. Slot buffers live in `SLOT`; the pump only
/// ever writes the `filling` slot, and the decoder only reads `decoding`.
struct Stream {
    file_lba: u32,
    done: bool,
    /// Video sectors that passed the checks.
    good: u32,
    /// Video sectors in the file (from the sector headers).
    total: u32,
    /// Next expected video ordinal.
    expected: u32,
    /// Ordinals skipped (never delivered).
    lost: u32,
    /// Sectors with a bad magic or checksum, or repeated / out of order.
    bad: u32,
    /// Absolute LBA of the last good sector.
    lba: u32,
    /// `lba` when the first LOST, BAD or drive error was seen.
    first_err_lba: Option<u32>,
    filling: usize,
    ready: Option<(usize, u32)>,
    decoding: Option<usize>,
    asm: FrameAssembler,
    late: u32,
    cd_errors: u32,
    last_sector_vblank: u32,
    /// Stop after this many video sectors (0: the whole file).
    cut: u32,
}

/// Own the drive and the MDEC for a run, replacing the previous run's.
fn install_devices(cd: Cd, mdec: MdecDma) {
    // SAFETY: single-threaded; nothing holds a reference from the previous run.
    unsafe {
        *addr_of_mut!(READER) = Some(SectorReader::with_cd(cd));
        *addr_of_mut!(MDEC) = Some(Mdec::new(mdec));
    }
}

/// The sector reader `install_devices` built.
fn reader() -> &'static mut SectorReader {
    // SAFETY: single-threaded, and no caller keeps the reference across a call
    // that takes another.
    unsafe { (*addr_of_mut!(READER)).as_mut().expect("reader installed") }
}

/// The MDEC driver `install_devices` built.
fn mdec() -> &'static mut Mdec {
    // SAFETY: as `reader`.
    unsafe { (*addr_of_mut!(MDEC)).as_mut().expect("mdec installed") }
}

fn slot_bytes(i: usize) -> &'static mut [u8] {
    // SAFETY: slots are disjoint statics; callers keep the pump's filling
    // slot and the decoder's slot distinct (see `Stream`).
    unsafe {
        let p = addr_of_mut!(SLOT[i]) as *mut u8;
        core::slice::from_raw_parts_mut(p, SLOT_WORDS * 4)
    }
}

impl Stream {
    /// Drain every sector the drive has ready.
    fn pump(&mut self) {
        clock(None);
        while !self.done {
            // SAFETY: single-threaded; SECTOR is only used here and by the
            // synchronous directory reads, never while a pump is running.
            let got = unsafe { reader().try_read_sector(&mut *addr_of_mut!(SECTOR)) };
            match got {
                Ok(true) => {}
                Ok(false) => return,
                Err(()) => {
                    self.cd_errors += 1;
                    self.first_err_lba.get_or_insert(self.lba);
                    self.done = true;
                    return;
                }
            }
            self.last_sector_vblank = interrupts::vblank_count();
            // SAFETY: SECTOR is a plain word buffer.
            let words = unsafe { &*addr_of_mut!(SECTOR) };
            if !self.check(words) {
                continue;
            }
            // SAFETY: the same buffer viewed as bytes.
            let sector = unsafe {
                core::slice::from_raw_parts(words.as_ptr() as *const u8, SECTOR_WORDS * 4)
            };
            if let Some(frame) = self.asm.add(sector, slot_bytes(self.filling)) {
                let done = self.filling;
                let next = match self.ready.replace((done, frame.size)) {
                    // The queued frame was never shown: skip it, reuse its slot.
                    Some((stale, _)) => {
                        self.late += 1;
                        stale
                    }
                    None => (0..SLOTS)
                        .find(|&s| s != done && Some(s) != self.decoding)
                        .unwrap_or(done),
                };
                self.filling = next;
            }
        }
    }

    /// Validate one video sector's test fields. `false` drops it.
    fn check(&mut self, w: &[u32; SECTOR_WORDS]) -> bool {
        let ordinal = w[5] & 0xFFFF;
        let mut h = SEED ^ ordinal;
        for &word in &w[8..] {
            h = h.rotate_left(5).wrapping_add(word);
        }
        if w[0] != STR_MAGIC || h != w[7] || ordinal < self.expected {
            self.bad += 1;
            self.first_err_lba.get_or_insert(self.lba);
            return false;
        }
        if ordinal > self.expected {
            self.lost += ordinal - self.expected;
            self.first_err_lba.get_or_insert(self.lba);
        }
        self.expected = ordinal + 1;
        self.total = w[5] >> 16;
        if self.cut != 0 && self.cut < self.total {
            self.total = self.cut;
        }
        self.lba = self.file_lba + w[6];
        self.good += 1;
        if self.expected >= self.total {
            self.done = true;
        }
        true
    }
}

/// Read one sector synchronously (directory lookups before streaming).
fn read_one(lba: u32) -> Option<&'static [u8]> {
    // SAFETY: single-threaded use of the reader and its sector buffer.
    unsafe {
        let r = reader();
        if !r.start_read(lba) {
            return None;
        }
        let ok = r.read_sector(&mut *addr_of_mut!(SECTOR));
        r.stop();
        if !ok {
            return None;
        }
        Some(core::slice::from_raw_parts(
            addr_of_mut!(SECTOR) as *const u8,
            SECTOR_WORDS * 4,
        ))
    }
}

fn find_movie() -> Option<(u32, u32)> {
    let (root, _) = iso::root_directory(read_one(iso::PVD_LBA)?)?;
    iso::find_in_directory(read_one(root)?, MOVIE)
}

/// Small fixed text buffer for overlay lines.
struct Text {
    buf: [u8; 40],
    len: usize,
}

impl Text {
    fn new() -> Self {
        Text {
            buf: [b' '; 40],
            len: 0,
        }
    }
    fn s(mut self, s: &str) -> Self {
        for &b in s.as_bytes() {
            if self.len < self.buf.len() {
                self.buf[self.len] = b;
                self.len += 1;
            }
        }
        self
    }
    /// Decimal, zero-padded to `width` digits.
    fn n(mut self, v: u32, width: usize) -> Self {
        let mut digits = [0u8; 10];
        let mut count = 0;
        let mut x = v;
        loop {
            digits[count] = b'0' + (x % 10) as u8;
            count += 1;
            x /= 10;
            if x == 0 {
                break;
            }
        }
        while count < width {
            digits[count] = b'0';
            count += 1;
        }
        for i in (0..count).rev() {
            if self.len < self.buf.len() {
                self.buf[self.len] = digits[i];
                self.len += 1;
            }
        }
        self
    }
    /// `mm:ss` from VBlanks (NTSC, 60 per second).
    fn time(self, vblanks: u32) -> Self {
        let secs = vblanks / 60;
        self.n(secs / 60, 2).s(":").n(secs % 60, 2)
    }
    fn as_str(&self) -> &str {
        core::str::from_utf8(&self.buf[..self.len]).unwrap_or("?")
    }
}

fn print_num(label: &str, v: u32) {
    tty::print(" ");
    tty::print(label);
    tty::print("=");
    tty::print(Text::new().n(v, 1).as_str());
}

/// Point GPU drawing at the 320x240 buffer starting at VRAM row `y`.
fn target(gpu: &mut Gpu, y: u16) {
    gpu.set_draw_area((0, y), (WIDTH - 1, y + HEIGHT - 1));
    gpu.set_draw_offset((0, y as i16));
}

/// Live counters, drawn over the bottom of the video frame.
fn draw_overlay(
    gpu: &mut Gpu,
    font: &FontAtlas,
    y: u16,
    st: &Stream,
    shown: u32,
    vblanks: u32,
    label: &str,
) {
    gpu.draw(&FillRect::new((0, y + 172), (WIDTH, 68), (0, 0, 0)));
    target(gpu, y);
    let l1 = Text::new().s("FR ").n(shown, 4).s("  LATE ").n(st.late, 4);
    let l2 = Text::new().s("LOST ").n(st.lost, 4).s(" BAD ").n(st.bad, 4);
    let l3 = Text::new().s("LBA ").n(st.lba, 6).s("  ").time(vblanks);
    let health = if st.lost == 0 && st.bad == 0 && st.cd_errors == 0 {
        GREEN
    } else {
        RED
    };
    font.draw_text(X0, 176, l1.as_str(), WHITE);
    font.draw_text(X0, 194, l2.as_str(), health);
    font.draw_text(X0, 212, l3.as_str(), WHITE);
    if !label.is_empty() {
        // A band over the top of the picture: the counters fill the bottom.
        gpu.draw(&FillRect::new((0, y), (WIDTH, 20), (0, 0, 0)));
        font.draw_text(X0, 2, label, YELLOW);
    }
}

struct Summary {
    pass: bool,
    shown: u32,
    dropped: u32,
    errors: u32,
    vblanks: u32,
    kcyc: [u32; 3],
}

/// Everything the summary screen shows, for a caller that records it.
#[derive(Copy, Clone, Debug, Default)]
pub struct Outcome {
    /// The PASS criteria: every video sector arrived intact and in order,
    /// every frame decoded, and the drive reported no error.
    pub pass: bool,
    /// Set when the test could not start (drive, file or MDEC setup); the
    /// counters below are then all zero.
    pub setup_error: Option<&'static str>,
    /// Video sectors that passed their checks, and the file's total.
    pub good: u32,
    pub total: u32,
    /// Video sectors never delivered, and ones delivered corrupt, repeated
    /// or out of order.
    pub lost: u32,
    pub bad: u32,
    /// Frames lost to bad sectors.
    pub dropped: u32,
    /// Drive error IRQs, and MDEC or bitstream failures.
    pub cd_errors: u32,
    pub decode_errors: u32,
    /// Frames shown, and frames skipped because the decoder was still busy
    /// (informational: CPU speed, not the disc).
    pub shown: u32,
    pub late: u32,
    /// Stream duration in VBlanks.
    pub vblanks: u32,
    /// Absolute LBA of the last good sector, and of the first problem.
    pub lba: u32,
    pub first_err_lba: Option<u32>,
    /// CPU cost per frame in kilocycles: bitstream decode, MDEC plus
    /// upload, and waiting.
    pub kcyc_vlc: u32,
    pub kcyc_mdec: u32,
    pub kcyc_wait: u32,
    /// Why the stream ended.
    pub stop: Stop,
    /// Video sectors the run was cut at (`Options::max_sectors`), or the
    /// file's total for a whole-movie run.
    pub target: u32,
}

/// Why a run ended.
#[derive(Copy, Clone, Debug, Default, PartialEq, Eq)]
#[repr(u8)]
pub enum Stop {
    /// Every video sector of the run arrived (the file's, or the cut's).
    #[default]
    End = 0,
    /// No sector for [`STALL_VBLANKS`]: the drive stopped delivering.
    Stall = 1,
    /// The MDEC failed [`WEDGE_ERRORS`] frames in a row.
    Wedged = 2,
    /// The drive reported an error.
    CdError = 3,
    /// Setup failed; nothing streamed.
    Setup = 4,
}

/// How a run is set up and how long it lasts.
#[derive(Copy, Clone)]
pub struct Options {
    /// MDEC setup (reset, tables, DMA requests), run at the start and again
    /// after a decode error; `false` when DMA0 decodes cannot run.
    pub setup: fn(&mut Mdec) -> bool,
    /// Stop after this many video sectors; 0 plays the whole file. The pass
    /// criteria then apply to the cut: every sector up to it intact.
    pub max_sectors: u32,
    /// Shown on the overlay and the summary, so a filmed run says which
    /// setup it used. Up to 12 characters; "" for none.
    pub label: &'static str,
}

impl Options {
    /// The whole movie behind the SDK's own setup.
    pub const DEFAULT: Options = Options {
        setup: mdec_setup,
        max_sectors: 0,
        label: "",
    };
}

/// Consecutive MDEC failures that end a run as [`Stop::Wedged`].
pub const WEDGE_ERRORS: u32 = 8;

/// Final screen: stays up after the stream ends.
fn draw_summary(
    gpu: &mut Gpu,
    font: &FontAtlas,
    small: &FontAtlas,
    st: &Stream,
    s: &Summary,
    label: &str,
) {
    gpu.draw(&FillRect::new((0, 0), (WIDTH, HEIGHT), (0, 0, 0)));
    target(gpu, 0);
    let verdict = if s.pass { "PASS" } else { "FAIL" };
    let tint = if s.pass { GREEN } else { RED };
    font.draw_text(32, 12, "FMV CONSOLE TEST", WHITE);
    small.draw_text(X0, 2, label, YELLOW);
    // Verdict banner: a solid block reads from across the room.
    gpu.draw(&FillRect::new((16, 32), (288, 32), tint));
    let ink = if s.pass { (0, 0, 0) } else { (255, 255, 255) };
    font.draw_text(64, 40, Text::new().s("RESULT: ").s(verdict).as_str(), ink);
    let lines = [
        (
            Text::new().s("SECT ").n(st.good, 1).s("/").n(st.total, 1),
            if st.good == st.total && st.total > 0 {
                GREEN
            } else {
                RED
            },
        ),
        (
            Text::new()
                .s("LOST ")
                .n(st.lost, 1)
                .s("  BAD ")
                .n(st.bad, 1),
            if st.lost == 0 && st.bad == 0 {
                GREEN
            } else {
                RED
            },
        ),
        (
            Text::new()
                .s("FRAMES ")
                .n(s.shown + st.late, 1)
                .s(" DROP ")
                .n(s.dropped, 1),
            if s.dropped == 0 { GREEN } else { RED },
        ),
        (
            Text::new()
                .s("SHW ")
                .n(s.shown, 4)
                .s(" LATE ")
                .n(st.late, 4),
            YELLOW,
        ),
        (
            Text::new()
                .s("CDERR ")
                .n(st.cd_errors, 1)
                .s(" DECERR ")
                .n(s.errors, 1),
            if st.cd_errors == 0 && s.errors == 0 {
                GREEN
            } else {
                RED
            },
        ),
        (
            Text::new().s("T ").time(s.vblanks).s(" LBA ").n(st.lba, 6),
            WHITE,
        ),
        match st.first_err_lba {
            None => (Text::new().s("ERR NEAR NONE"), GREEN),
            Some(l) => (Text::new().s("ERR NEAR ").n(l, 6), RED),
        },
    ];
    let mut y = 74;
    for (text, tint) in &lines {
        font.draw_text(X0, y, text.as_str(), *tint);
        y += 18;
    }
    let small_line = Text::new()
        .s("KCYC VLC ")
        .n(s.kcyc[PHASE_VLC], 1)
        .s(" MDEC ")
        .n(s.kcyc[PHASE_MDEC], 1)
        .s(" WAIT ")
        .n(s.kcyc[PHASE_WAIT], 1);
    small.draw_text(X0, 204, small_line.as_str(), WHITE);
    small.draw_text(X0, 214, "LATE: DECODER SLOW, NOT A FAIL", WHITE);
    gpu.wait_idle();
    gpu.set_display_start((0, 0));
}

/// The test could not start: a red screen, and the reason on the TTY.
fn fail(gpu: &mut Gpu, what: &'static str) -> Outcome {
    tty::print("FMV FAIL ");
    tty::println(what);
    gpu.draw(&FillRect::new((0, 0), (WIDTH, HEIGHT), (160, 0, 0)));
    gpu.set_display_start((0, 0));
    Outcome {
        setup_error: Some(what),
        stop: Stop::Setup,
        ..Outcome::default()
    }
}

/// Wait for the next VBlank edge while keeping the drive drained.
fn wait_vblank_pumping(st: &mut Stream) {
    let start = interrupts::vblank_count();
    while interrupts::vblank_count() == start {
        st.pump();
    }
}

/// The SDK's MDEC setup: reset, then the tables. `false` unless DMA0 can
/// feed the decoder afterwards, which every frame needs.
pub fn mdec_setup(mdec: &mut Mdec) -> bool {
    mdec.reset() && mdec.load_tables().is_some_and(|t| t.enable_writes != 0)
}

/// Run the whole test: stream, check, and leave the summary (or, when the
/// test could not start, a red screen) on the displayed buffer at VRAM row 0.
/// Takes over the GPU, SPU, CD drive, MDEC and root counter 2; a caller that
/// carries on afterwards restores what it needs.
pub fn run() -> Outcome {
    run_with(Options::DEFAULT)
}

/// [`run`] with the caller's MDEC setup and length. The hardware-test suite
/// plays a short cut behind each of its diagnostic sequences that worked.
pub fn run_with(options: Options) -> Outcome {
    let setup = options.setup;
    // SAFETY: the test takes over the GPU, SPU, CD drive and MDEC, as its doc
    // says; it runs from a menu that may already have used them, so it takes the
    // set afresh. Nothing else drives them until the test returns.
    let peripherals = unsafe { Peripherals::steal() };
    install_devices(peripherals.cd, peripherals.mdec_dma);
    let gpu = &mut Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    gpu.draw(&FillRect::new((0, 0), (WIDTH, 512), (0, 0, 0)));
    let font = FontAtlas::upload(&WIDE, FONT_TPAGE, FONT_CLUT);
    let small = FontAtlas::upload(&BASIC, SMALL_TPAGE, SMALL_CLUT);

    let _spu = Spu::new(peripherals.spu_dma);
    spu::set_main_volume(Volume::MAX, Volume::MAX);
    spu::set_cd_volume(CdVolume::MAX, CdVolume::MAX);
    spu::enable_cd_audio(true);

    // The reader owns the CD token for the run; prepare also takes the drive
    // over from whatever used it before.
    if !reader().prepare() {
        return fail(gpu, "cd prepare");
    }
    let Some((lba, _size)) = find_movie() else {
        return fail(gpu, "MOVIE.STR not found");
    };
    // The reader is prepared and idle. Unmute first: a muted drive plays no XA,
    // and the program that ran before may have left it muted (the hardware-test
    // CD battery does).
    let xa_ok = {
        let r = reader();
        r.unmute() && r.prepare_mode(CD_MODE) && r.set_filter(XA_FILE, XA_CHANNEL)
    };
    if !xa_ok {
        return fail(gpu, "cd xa mode");
    }
    reader().cd_mut().set_audio_mixer(0x80, 0, 0x80, 0);
    if !setup(mdec()) {
        return fail(gpu, "mdec tables");
    }

    let mut st = Stream {
        file_lba: lba,
        done: false,
        good: 0,
        total: 0,
        expected: 0,
        lost: 0,
        bad: 0,
        lba,
        first_err_lba: None,
        filling: 0,
        ready: None,
        decoding: None,
        asm: FrameAssembler::new(),
        late: 0,
        cd_errors: 0,
        last_sector_vblank: interrupts::vblank_count(),
        cut: options.max_sectors,
    };
    // The reader was prepared above.
    if !reader().start_read(lba) {
        return fail(gpu, "cd start");
    }

    let mut shown = 0u32;
    let mut errors = 0u32;
    let mut in_a_row = 0u32;
    let mut wedged = false;
    let mut back_y: u16 = 256;
    // Counter 2 on the system clock / 8, free-running.
    psx_io::timers::set_mode(
        psx_io::timers::Timer::Timer2,
        psx_hw::timers::mode::clock_source(2),
    );
    clock(Some(PHASE_WAIT));
    // SAFETY: single-threaded profiling statics; a second run from a menu
    // starts its profile from zero.
    unsafe { *addr_of_mut!(ACC) = [0; 3] };
    let start = interrupts::vblank_count();
    let mut next_flip = start;
    // SAFETY: RLE is only touched by this loop, through this one reference.
    let rle = unsafe { &mut *addr_of_mut!(RLE) };

    loop {
        st.pump();
        let Some((slot, bytes)) = st.ready.take() else {
            let idle = interrupts::vblank_count().wrapping_sub(st.last_sector_vblank);
            if st.done || idle > STALL_VBLANKS {
                break;
            }
            continue;
        };
        clock(Some(PHASE_VLC));
        st.decoding = Some(slot);
        let frame = &slot_bytes(slot)[..(bytes as usize).min(SLOT_WORDS * 4)];
        let decoded = bitstream::decode_frame(
            frame,
            rle.as_halfwords_mut(),
            COLUMNS as u32 * ROWS,
            ROWS,
            &mut || st.pump(),
        );
        st.decoding = None; // the bitstream is fully consumed
        let words = match decoded {
            Ok(w) => w,
            Err(_) => {
                errors += 1;
                continue;
            }
        };
        clock(Some(PHASE_MDEC));
        // SAFETY: COLUMN is only used here.
        let column = unsafe { &mut *addr_of_mut!(COLUMN) };
        // DMA0 feeds the MDEC while the closure pulls each column over DMA1;
        // `decode` holds the run-length borrow until DMA0 is done with it.
        let decoded = mdec().decode(
            &rle.as_words()[..words],
            psx_hw::mdec::DECODE_15BPP,
            |mdec| {
                for c in 0..COLUMNS {
                    if !mdec.read_column(column) {
                        return false;
                    }
                    psx_vram::upload_words(VramRect::new(c * 16, back_y, 16, HEIGHT), column);
                    st.pump();
                }
                true
            },
        );
        if !matches!(decoded, Ok((true, true))) {
            errors += 1;
            in_a_row += 1;
            if in_a_row >= WEDGE_ERRORS {
                wedged = true;
                break;
            }
            let _ = setup(mdec());
            continue;
        }
        in_a_row = 0;
        let elapsed = interrupts::vblank_count().wrapping_sub(start);
        draw_overlay(gpu, &font, back_y, &st, shown + 1, elapsed, options.label);
        gpu.wait_idle();
        clock(Some(PHASE_WAIT));
        // Pace to 15 fps, then flip at the VBlank; the drive keeps draining.
        while (interrupts::vblank_count().wrapping_sub(next_flip) as i32) < 0 {
            st.pump();
        }
        wait_vblank_pumping(&mut st);
        gpu.set_display_start((0, back_y));
        next_flip = interrupts::vblank_count().wrapping_add(VBLANKS_PER_FRAME - 1);
        back_y = if back_y == 0 { 256 } else { 0 };
        shown += 1;
    }
    // Stop the stream we started (also ends the XA audio).
    reader().stop();
    let vblanks = interrupts::vblank_count().wrapping_sub(start);
    let stop = if wedged {
        Stop::Wedged
    } else if st.cd_errors != 0 {
        Stop::CdError
    } else if st.done {
        Stop::End
    } else {
        Stop::Stall
    };
    if st.expected < st.total {
        st.lost += st.total - st.expected;
        st.first_err_lba.get_or_insert(st.lba);
    }

    let acc = unsafe { *addr_of_mut!(ACC) };
    let per = (shown + st.late).max(1);
    let summary = Summary {
        pass: st.total > 0
            && st.good == st.total
            && st.lost == 0
            && st.bad == 0
            && st.cd_errors == 0
            && errors == 0
            && st.asm.dropped == 0,
        shown,
        dropped: st.asm.dropped,
        errors,
        vblanks,
        kcyc: [
            acc[PHASE_VLC] / per * 8 / 1000,
            acc[PHASE_MDEC] / per * 8 / 1000,
            acc[PHASE_WAIT] / per * 8 / 1000,
        ],
    };
    tty::print(if summary.pass { "FMV PASS" } else { "FMV FAIL" });
    print_num("sectors", st.good);
    print_num("total", st.total);
    print_num("lost", st.lost);
    print_num("bad", st.bad);
    print_num("frames", shown);
    print_num("late", st.late);
    print_num("dropped", st.asm.dropped);
    print_num("errors", errors);
    print_num("cd_errors", st.cd_errors);
    print_num("vblanks", vblanks);
    print_num("kcyc_vlc", summary.kcyc[PHASE_VLC]);
    print_num("kcyc_mdec_upload", summary.kcyc[PHASE_MDEC]);
    print_num("kcyc_wait", summary.kcyc[PHASE_WAIT]);
    print_num("stop", stop as u32);
    print_num("target", st.total);
    tty::println("");
    draw_summary(gpu, &font, &small, &st, &summary, options.label);
    Outcome {
        pass: summary.pass,
        setup_error: None,
        good: st.good,
        total: st.total,
        lost: st.lost,
        bad: st.bad,
        dropped: summary.dropped,
        cd_errors: st.cd_errors,
        decode_errors: summary.errors,
        shown: summary.shown,
        late: st.late,
        vblanks: summary.vblanks,
        lba: st.lba,
        first_err_lba: st.first_err_lba,
        kcyc_vlc: summary.kcyc[PHASE_VLC],
        kcyc_mdec: summary.kcyc[PHASE_MDEC],
        kcyc_wait: summary.kcyc[PHASE_WAIT],
        stop,
        target: st.total,
    }
}

/// A one-frame control decode: the movie's first frame through the MDEC
/// twice, once fed and drained by CPU writes and reads, once over DMA0 and
/// DMA1 as the player does. Equal sums mean both paths decode the same
/// pixels. The sums add the output words, so they do not depend on the
/// block order, which DMA1 rearranges and CPU reads do not.
#[derive(Copy, Clone, Debug, Default)]
pub struct FrameControl {
    /// The frame was read and its bitstream decoded.
    pub read: bool,
    /// Run-length words the MDEC was given, and output words expected.
    pub rle_words: u32,
    pub expected: u32,
    /// CPU path: finished, output words drained, their sum.
    pub cpu_ok: bool,
    pub cpu_words: u32,
    pub cpu_sum: u32,
    /// DMA path (behind `dma_setup`): finished, words, sum.
    pub dma_ok: bool,
    pub dma_words: u32,
    pub dma_sum: u32,
}

/// Spins without progress before the CPU decode gives up.
const CPU_STALL_SPINS: u32 = 100_000;

/// Run [`FrameControl`]. Takes the CD drive and the MDEC; `dma_setup` is the
/// MDEC setup for the DMA half.
pub fn frame_control(dma_setup: fn(&mut Mdec) -> bool) -> FrameControl {
    let mut out = FrameControl::default();
    // SAFETY: takes the CD drive and the MDEC afresh, as `run_with` does.
    let peripherals = unsafe { Peripherals::steal() };
    install_devices(peripherals.cd, peripherals.mdec_dma);
    if !reader().prepare() {
        return out;
    }
    let Some((lba, _)) = find_movie() else {
        return out;
    };
    // Plain data reads: the XA audio sectors come back too and are skipped.
    if !reader().start_read(lba) {
        return out;
    }
    let mut asm = FrameAssembler::new();
    let mut frame = None;
    for _ in 0..48 {
        // SAFETY: SECTOR is only used by this loop and `find_movie` before it.
        if !reader().read_sector(unsafe { &mut *addr_of_mut!(SECTOR) }) {
            break;
        }
        let words = unsafe { &*addr_of_mut!(SECTOR) };
        if words[0] != STR_MAGIC {
            continue;
        }
        let sector =
            unsafe { core::slice::from_raw_parts(words.as_ptr() as *const u8, SECTOR_WORDS * 4) };
        if let Some(f) = asm.add(sector, slot_bytes(0)) {
            frame = Some(f);
            break;
        }
    }
    reader().stop();
    let Some(frame) = frame else {
        return out;
    };
    // SAFETY: as above; this is the only reference to RLE while it lives.
    let rle = unsafe { &mut *addr_of_mut!(RLE) };
    let bytes = &slot_bytes(0)[..(frame.size as usize).min(SLOT_WORDS * 4)];
    let decoded = bitstream::decode_frame(
        bytes,
        rle.as_halfwords_mut(),
        COLUMNS as u32 * ROWS,
        ROWS,
        &mut || {},
    );
    let Ok(words) = decoded else {
        return out;
    };
    let rle = &rle.as_words()[..words];
    out.read = true;
    out.rle_words = words as u32;
    out.expected = COLUMNS as u32 * ROWS * 128;

    // CPU: feed while the input FIFO has room, drain whatever comes out.
    if mdec().reset() && mdec().load_tables_cpu() {
        mdec().write_command(psx_hw::mdec::DECODE_15BPP | (words as u32 & 0xFFFF));
        let mut fed = 0usize;
        let mut idle = 0u32;
        while (fed < words || out.cpu_words < out.expected) && idle < CPU_STALL_SPINS {
            let status = psx_fmv::mdec::status();
            let mut progress = false;
            if fed < words && status & psx_hw::mdec::STATUS_IN_FULL == 0 {
                mdec().write_command(rle[fed]);
                fed += 1;
                progress = true;
            }
            if status & psx_hw::mdec::STATUS_OUT_EMPTY == 0 {
                out.cpu_sum = out.cpu_sum.wrapping_add(mdec().read_data());
                out.cpu_words += 1;
                progress = true;
            }
            idle = if progress { 0 } else { idle + 1 };
        }
        out.cpu_ok = fed == words && out.cpu_words == out.expected;
    }

    // DMA, the player's way.
    if dma_setup(mdec()) {
        // SAFETY: COLUMN is only used here.
        let column = unsafe { &mut *addr_of_mut!(COLUMN) };
        let decoded = mdec().decode(rle, psx_hw::mdec::DECODE_15BPP, |mdec| {
            for _ in 0..COLUMNS {
                if !mdec.read_column(column) {
                    return false;
                }
                for &w in column.iter() {
                    out.dma_sum = out.dma_sum.wrapping_add(w);
                }
                out.dma_words += COLUMN_WORDS as u32;
            }
            true
        });
        out.dma_ok = matches!(decoded, Ok((true, true)));
    }
    tty::print("FMV CONTROL");
    print_num("read", out.read as u32);
    print_num("rle_words", out.rle_words);
    print_num("cpu_ok", out.cpu_ok as u32);
    print_num("cpu_words", out.cpu_words);
    print_num("cpu_sum", out.cpu_sum);
    print_num("dma_ok", out.dma_ok as u32);
    print_num("dma_words", out.dma_words);
    print_num("dma_sum", out.dma_sum);
    tty::println("");
    // Leave the MDEC as the player expects to find it.
    let _ = mdec().reset();
    out
}

//! `hello-gte` -- spin a 3D cube via the GTE, using the SDK math layer.
//!
//! Reads like a normal 3D engine: build a rotation, load it, project
//! vertices, draw edges. Rotation spins yaw × pitch so the cube's
//! depth is obvious. Angles are `Mat3I16::rotate_*` 256-per-revolution
//! units; a ×4 step on the frame counter gives one full Y-rev per 64
//! frames (≈1 s at 60 fps).
//!
//! Edges drawn as `LineMono` packets (GP0 0x40, real diagonal
//! rasteriser). The previous version of this example used
//! `fill_rect`-per-pixel, which the PSX's GP0 0x02 fill primitive
//! rounds to 16-pixel X boundaries -- the result was blocky noise
//! rather than a visible wireframe.

#![no_std]
#![no_main]

extern crate psx_rt;

use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::prim::LineMono;
use psx_gpu::Gpu;
use psx_gte::math::{Mat3I16, Vec3I16, Vec3I32};
use psx_gte::scene;
use psx_rt::tty;

/// Eight corners of a unit cube, centred at the origin, in 1.3.12
/// fixed point -- `0x0800` = 0.5.
const CUBE_VERTS: [Vec3I16; 8] = [
    Vec3I16::new(-0x0800, -0x0800, -0x0800),
    Vec3I16::new(0x0800, -0x0800, -0x0800),
    Vec3I16::new(0x0800, 0x0800, -0x0800),
    Vec3I16::new(-0x0800, 0x0800, -0x0800),
    Vec3I16::new(-0x0800, -0x0800, 0x0800),
    Vec3I16::new(0x0800, -0x0800, 0x0800),
    Vec3I16::new(0x0800, 0x0800, 0x0800),
    Vec3I16::new(-0x0800, 0x0800, 0x0800),
];

/// Index pairs that form cube edges. Four back-face edges, four
/// front-face edges, four connectors.
const CUBE_EDGES: [(usize, usize); 12] = [
    (0, 1),
    (1, 2),
    (2, 3),
    (3, 0),
    (4, 5),
    (5, 6),
    (6, 7),
    (7, 4),
    (0, 4),
    (1, 5),
    (2, 6),
    (3, 7),
];

/// Angle step per frame (256 = one full revolution). 4 → 64 frames
/// per rev. Different multipliers on yaw vs pitch so the cube
/// precesses as well as spins.
const YAW_STEP: u16 = 4;
const PITCH_STEP: u16 = 3;

#[no_mangle]
fn main() {
    tty::println("hello-gte: booted");

    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    // Double-buffer: tear-free cube spinning, even under the
    // mono-line rasteriser's per-pixel cost.
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));

    // One-shot scene setup. OFX/OFY in 15.16 fixed-point centre the
    // projection at the screen middle. H=200 is a reasonable focal
    // length at z≈3.0; the Z translation pushes the cube into the
    // scene so RTPS's perspective divide stays well-defined.
    scene::set_screen_offset(160 << 16, 120 << 16);
    scene::set_projection_plane(200);
    scene::load_translation(Vec3I32::new(0, 0, 0x3000));

    let mut frame: u16 = 0;
    loop {
        fb.clear(&mut gpu, (0, 0, 32));

        // Compose yaw × pitch on the CPU, upload once to GTE R0..R4.
        let yaw = Mat3I16::rotate_y(frame.wrapping_mul(YAW_STEP));
        let pitch = Mat3I16::rotate_x(frame.wrapping_mul(PITCH_STEP));
        let rot = yaw.mul(&pitch);
        scene::load_rotation(&rot);

        // Project every vertex via RTPS → screen-space (sx, sy).
        let mut projected: [(i16, i16); 8] = [(0, 0); 8];
        for (i, v) in CUBE_VERTS.iter().enumerate() {
            let p = scene::project_vertex(*v);
            projected[i] = (p.sx, p.sy);
        }

        // Twelve real GPU lines -- GP0 0x40.
        for &(a, b) in &CUBE_EDGES {
            let (ax, ay) = projected[a];
            let (bx, by) = projected[b];
            gpu.draw(&LineMono::new(ax, ay, bx, by, 255, 255, 255));
        }

        if frame == 0 {
            let flag = scene::error_flags();
            if flag != 0 {
                tty::println("hello-gte: GTE flag non-zero at first frame");
            }
        }

        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
        frame = frame.wrapping_add(1);
    }
}

//! `hello-gteirq` -- does a GTE command run exactly once when a VBlank
//! interrupt lands on it?
//!
//! On silicon an interrupt taken on a GTE command lets the command run and
//! still reports EPC at it, so a handler that returns to EPC runs it twice
//! (hardware-tests v1.24, case 0xC9: 38 of 38). psx-rt's handler steps over
//! a GTE command at EPC instead (case 0xCB: 61 skips, none doubled or lost).
//! This example runs the v1.24 probe's pattern under psx-rt's own handler:
//! load SXY0-2 with three markers, RTPS, wait out its latency, read SXY0.
//! One RTPS shifts the screen-XY FIFO once, so SXY0 must hold the second
//! marker; two shifts leave the third, none the first. The markers' high
//! halves lie outside the range RTPS saturates to, so no projection can
//! pass for one. The loop runs for `VBLANKS` VBlank interrupts.
//!
//! The verdict goes to the TTY (`GTEIRQ PASS ...` or `GTEIRQ FAIL ...`) and
//! on screen. `gte_skips` counts the interrupts the handler stepped over a
//! GTE command for: about one in forty VBlanks on silicon, where the loop is
//! mostly RTPS-adjacent instructions. Since emulator commit c7e3ea8 PSoXide
//! also takes an interrupt with EPC on a GTE command, as silicon does, so
//! the probe can fail there too; a console run remains the reference.

#![no_std]
#![no_main]
#![feature(asm_experimental_arch)]

extern crate psx_rt;

use psx_font::{fonts::BASIC, FontAtlas};
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_rt::interrupts;
use psx_rt::tty;
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);
const WHITE: (u8, u8, u8) = (220, 220, 230);
const GREEN: (u8, u8, u8) = (80, 220, 100);
const RED: (u8, u8, u8) = (230, 80, 80);

/// Written to SXY0/SXY1/SXY2 before each RTPS. After one RTPS SXY0 holds
/// B, after two C, after none A.
const SXY_A: u32 = 0x5A5A_1111;
const SXY_B: u32 = 0x5A5A_2222;
const SXY_C: u32 = 0x5A5A_3333;
/// Iterations between checks of the VBlank count.
const CHUNK: u32 = 4096;
/// Interrupts to run under: about five seconds on NTSC.
const VBLANKS: u32 = 300;

#[derive(Clone, Copy, Default)]
struct Counts {
    ok: u32,
    doubled: u32,
    missing: u32,
    other: u32,
}

/// `iterations` x (reload SXY0-2, RTPS, wait it out, classify SXY0).
///
/// The RTPS never sits in a delay slot (psx-rt's fix cannot cover one).
/// Twenty nops cover its latency before the read, so a stale read cannot
/// pass for a missing command.
fn gte_loop(iterations: u32, counts: &mut Counts) {
    let (mut ok, mut doubled, mut missing, mut other) =
        (counts.ok, counts.doubled, counts.missing, counts.other);
    unsafe {
        core::arch::asm!(
            ".set noreorder",
            "1:",
            ".word 0x48896000", // mtc2 $9, SXY0
            ".word 0x488A6800", // mtc2 $10, SXY1
            ".word 0x488B7000", // mtc2 $11, SXY2
            "nop",
            "nop",
            ".word 0x4A180001", // RTPS
            ".rept 20",
            "nop",
            ".endr",
            ".word 0x480C6000", // mfc2 $12, SXY0
            "nop",
            "beq $12, $10, 2f",
            "addiu $8, $8, -1",
            "beq $12, $11, 3f",
            "nop",
            "beq $12, $9, 4f",
            "nop",
            "addiu $24, $24, 1",
            "b 5f",
            "nop",
            "2:",
            "addiu $13, $13, 1",
            "b 5f",
            "nop",
            "3:",
            "addiu $14, $14, 1",
            "b 5f",
            "nop",
            "4:",
            "addiu $15, $15, 1",
            "5:",
            "bnez $8, 1b",
            "nop",
            ".set reorder",
            inout("$8") iterations => _,
            in("$9") SXY_A,
            in("$10") SXY_B,
            in("$11") SXY_C,
            lateout("$12") _,
            inout("$13") ok,
            inout("$14") doubled,
            inout("$15") missing,
            inout("$24") other,
            options(nostack)
        );
    }
    counts.ok = ok;
    counts.doubled = doubled;
    counts.missing = missing;
    counts.other = other;
}

/// `label=XXXXXXXX` for the TTY and the screen.
fn line(label: &str, value: u32) -> ([u8; 32], usize) {
    const DIGITS: &[u8; 16] = b"0123456789ABCDEF";
    let mut text = [b' '; 32];
    let label = &label.as_bytes()[..label.len().min(22)];
    text[..label.len()].copy_from_slice(label);
    text[label.len()] = b'=';
    for i in 0..8 {
        text[label.len() + 1 + i] = DIGITS[(value >> (28 - 4 * i) & 0xF) as usize];
    }
    (text, label.len() + 9)
}

fn as_str(text: &[u8]) -> &str {
    core::str::from_utf8(text).unwrap_or("?")
}

#[no_mangle]
fn main() {
    // Also sets SR.CU2, which the GTE needs.
    interrupts::install_vblank_counter();

    let skips_before = interrupts::gte_skip_count();
    let start = interrupts::vblank_count();
    let mut counts = Counts::default();
    let mut iterations = 0u32;
    while interrupts::vblank_count().wrapping_sub(start) < VBLANKS {
        gte_loop(CHUNK, &mut counts);
        iterations = iterations.wrapping_add(CHUNK);
    }
    let vblanks = interrupts::vblank_count().wrapping_sub(start);
    let skips = interrupts::gte_skip_count().wrapping_sub(skips_before);

    let checks = [
        (counts.doubled == 0, "an RTPS ran twice"),
        (counts.missing == 0, "an RTPS was lost"),
        (counts.other == 0, "SXY0 held no marker"),
        (counts.ok == iterations, "not every iteration counted"),
        (interrupts::fault_count() == 0, "exceptions other than IRQs"),
    ];
    let failures = checks.iter().filter(|check| !check.0).count() as u32;
    for (_, what) in checks.iter().filter(|check| !check.0) {
        tty::print("GTEIRQ check failed: ");
        tty::println(what);
    }
    let lines = [
        line("failures", failures),
        line("iterations", iterations),
        line("vblanks", vblanks),
        line("gte_skips", skips),
        line("doubled", counts.doubled),
        line("missing", counts.missing),
    ];
    let (banner, tint) = if failures == 0 {
        ("GTEIRQ PASS", GREEN)
    } else {
        ("GTEIRQ FAIL", RED)
    };
    tty::print(banner);
    for (text, len) in &lines {
        tty::print(" ");
        tty::print(as_str(&text[..*len]));
    }
    tty::println("");

    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);
    loop {
        fb.clear(&mut gpu, (10, 12, 20));
        font.draw_text(8, 6, "GTE COMMANDS UNDER VBLANK IRQS", WHITE);
        font.draw_text(8, 30, banner, tint);
        for (row, (text, len)) in lines.iter().enumerate() {
            font.draw_text(8, 54 + 12 * row as i16, as_str(&text[..*len]), WHITE);
        }
        let mut y = 138;
        for (_, what) in checks.iter().filter(|check| !check.0) {
            font.draw_text(8, y, what, RED);
            y += 12;
        }
        gpu.wait_idle();
        interrupts::wait_vblank();
        fb.swap(&mut gpu);
    }
}

//! `hello-i64probe` -- does software 64-bit integer arithmetic execute
//! correctly on the PS1 (via compiler-builtins' `__muldi3` / `__divdi3` etc.)?
//!
//! Each operand is run through `core::hint::black_box` so nothing const-folds on
//! the host: the multiply / divide compile to real runtime calls the target CPU
//! must execute. A green `ALL PASS` means i64 works on hardware/emulator.
//!
//! This probe uncovered a real bug: compiler-builtins' **signed** 64-bit divide
//! (`__divdi3`) returns garbage on this target, while unsigned mul/div/mod work.
//! `psx-rt` now overrides `__divdi3`/`__moddi3` with a correct implementation, so
//! the `signed / and %` case here passes purely from linking psx-rt.

#![no_std]
#![no_main]

extern crate psx_rt;

use core::hint::black_box;
use psx_font::{fonts::BASIC, FontAtlas};
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);

const GREEN: (u8, u8, u8) = (80, 220, 100);
const RED: (u8, u8, u8) = (230, 80, 80);

struct Case {
    label: &'static str,
    got: i64,
    want: i64,
}

/// Fixed-point multiply a*b/ONE done in UNSIGNED magnitude (avoids the broken
/// signed __divdi3), sign handled by hand.
fn fmul64(a: i64, b: i64, one: u64) -> i64 {
    let neg = (a < 0) ^ (b < 0);
    let m = (a.unsigned_abs() * b.unsigned_abs()) / one; // u64 mul + u64 div
    if neg {
        -(m as i64)
    } else {
        m as i64
    }
}
/// Fixed-point divide a*ONE/b in unsigned magnitude.
fn fdiv64(a: i64, b: i64, one: u64) -> i64 {
    let neg = (a < 0) ^ (b < 0);
    let m = (a.unsigned_abs() * one) / b.unsigned_abs();
    if neg {
        -(m as i64)
    } else {
        m as i64
    }
}

fn cases(out: &mut [Case; 8]) -> usize {
    let one = black_box(1_000_000u64);
    // Unsigned 64-bit multiply / divide / mod (these should be the good path).
    out[0] = Case {
        label: "u64 mul",
        got: (black_box(300_000u64) * black_box(150_000u64)) as i64,
        want: 45_000_000_000,
    };
    out[1] = Case {
        label: "u64 div",
        got: (black_box(45_000_000_000u64) / black_box(1000u64)) as i64,
        want: 45_000_000,
    };
    out[2] = Case {
        label: "u64 mod",
        got: (black_box(45_000_000_007u64) % black_box(1000u64)) as i64,
        want: 7,
    };
    // The workaround the spreadsheet would use: signed via unsigned magnitude.
    out[3] = Case {
        label: "fmul64 1.5*2",
        got: fmul64(black_box(1_500_000), black_box(2_000_000), one),
        want: 3_000_000,
    };
    out[4] = Case {
        label: "fdiv64 10/3",
        got: fdiv64(black_box(10_000_000), black_box(3_000_000), one),
        want: 3_333_333,
    };
    out[5] = Case {
        label: "fdiv64 -10/3",
        got: fdiv64(black_box(-10_000_000), black_box(3_000_000), one),
        want: -3_333_333,
    };
    out[6] = Case {
        label: "big u64 div",
        got: (black_box(9_876_543_210_000u64) / black_box(1_000_000u64)) as i64,
        want: 9_876_543,
    };
    // Direct SIGNED i64 divide + mod. These returned garbage from the stock
    // compiler-builtins; psx-rt now overrides __divdi3/__moddi3, so they pass.
    out[7] = Case {
        label: "signed / and %",
        got: black_box(-123_456_789i64) / black_box(1000i64)
            + black_box(-7i64) % black_box(1000i64),
        want: -123_463, // -123456 + -7
    };
    8
}

#[no_mangle]
fn main() {
    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);

    let mut buf = [Case {
        label: "",
        got: 0,
        want: 0,
    }; 8];
    let n = cases(&mut buf);
    let all_ok = buf[..n].iter().all(|c| c.got == c.want);

    loop {
        fb.clear(&mut gpu, (10, 12, 20));
        font.draw_text(8, 6, "I64 PROBE (black_box)", (220, 220, 230));
        let mut y: i16 = 26;
        for c in buf[..n].iter() {
            let ok = c.got == c.want;
            let tint = if ok { GREEN } else { RED };
            font.draw_text(8, y, if ok { "OK" } else { "XX" }, tint);
            font.draw_text(32, y, c.label, tint);
            let mut nb = [0u8; 24];
            let s = fmt_i64(c.got, &mut nb);
            font.draw_text(180, y, s, tint);
            y += 12;
        }
        let (banner, bt) = if all_ok {
            ("ALL PASS", GREEN)
        } else {
            ("FAIL", RED)
        };
        font.draw_text(8, y + 8, banner, bt);

        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
    }
}

impl Copy for Case {}
impl Clone for Case {
    fn clone(&self) -> Self {
        *self
    }
}

/// Format an i64 as decimal into `out`, returning the `&str`.
fn fmt_i64(v: i64, out: &mut [u8]) -> &str {
    let neg = v < 0;
    let mut mag = v.unsigned_abs();
    let mut tmp = [0u8; 20];
    let mut i = 0;
    if mag == 0 {
        tmp[0] = b'0';
        i = 1;
    }
    while mag > 0 {
        tmp[i] = b'0' + (mag % 10) as u8;
        mag /= 10;
        i += 1;
    }
    let mut n = 0;
    if neg {
        out[n] = b'-';
        n += 1;
    }
    for j in (0..i).rev() {
        out[n] = tmp[j];
        n += 1;
    }
    // SAFETY: only ASCII digits and '-'.
    unsafe { core::str::from_utf8_unchecked(&out[..n]) }
}

//! `hello-icache` -- does `psx_rt::cache::flush_instruction_cache` make the
//! CPU fetch code that was just rewritten in RAM?
//!
//! A three-word function in cached RAM returns a constant:
//! `addiu $v0, $zero, K; jr $ra; nop`. The probe:
//!
//! 1. writes it with K = 1, flushes, calls it (expects 1; the call also
//!    loads the line into the instruction cache);
//! 2. rewrites K = 2 with a plain store and calls it again without a
//!    flush. A store doesn't update the instruction cache, so a cache that
//!    still holds the line runs the old word and returns 1;
//! 3. flushes and calls once more (expects 2).
//!
//! `ICACHE PASS` needs 1, 1, 2: step 2 proves the line was really cached,
//! so step 3 proves the flush dropped it. If step 2 already returns 2 the
//! run says `ICACHE INCONCLUSIVE`: nothing was stale, so the flush wasn't
//! tested. The verdict goes to the TTY and the screen.

#![no_std]
#![no_main]

extern crate psx_rt;

use psx_font::{fonts::BASIC, FontAtlas};
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_rt::{cache::flush_instruction_cache, tty};
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);

/// `addiu $v0, $zero, 0` (opcode 9, rt = 2); the low 16 bits are the
/// immediate.
const ADDIU_V0_ZERO: u32 = 0x2402_0000;
/// `jr $ra`.
const JR_RA: u32 = 0x03E0_0008;

/// One cache line (16 bytes) of code, line aligned so the function sits
/// in a single line.
#[repr(C, align(16))]
struct Line([u32; 4]);

static mut CODE: Line = Line([ADDIU_V0_ZERO | 1, JR_RA, 0, 0]);

/// Store a new immediate into the function's first word.
fn patch(value: u16) {
    // SAFETY: CODE is only touched from this single-threaded program.
    unsafe { (&raw mut CODE.0[0]).write_volatile(ADDIU_V0_ZERO | u32::from(value)) };
}

/// Call the function in CODE.
#[inline(never)]
fn call() -> u32 {
    // SAFETY: CODE holds a complete O32 leaf function (load $v0, return).
    unsafe {
        let f: extern "C" fn() -> u32 = core::mem::transmute(&raw const CODE);
        f()
    }
}

#[no_mangle]
fn main() {
    patch(1);
    flush_instruction_cache();
    let first = call();
    patch(2);
    let stale = call();
    flush_instruction_cache();
    let fresh = call();

    let (verdict, tint) = if first == 1 && stale == 1 && fresh == 2 {
        ("ICACHE PASS", (80, 220, 100))
    } else if first == 1 && stale == 2 && fresh == 2 {
        ("ICACHE INCONCLUSIVE", (230, 200, 80))
    } else {
        ("ICACHE FAIL", (230, 80, 80))
    };
    tty::print(verdict);
    for (label, value) in [(" first=", first), (" stale=", stale), (" fresh=", fresh)] {
        tty::print(label);
        tty::print_hex_u32(value);
    }
    tty::println("");

    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);
    let digit = |v: u32| -> &'static str {
        match v {
            1 => "1",
            2 => "2",
            _ => "?",
        }
    };
    loop {
        fb.clear(&mut gpu, (10, 12, 20));
        font.draw_text(8, 6, "I-CACHE FLUSH PROBE", (220, 220, 230));
        font.draw_text(8, 26, "first", (220, 220, 230));
        font.draw_text(80, 26, digit(first), tint);
        font.draw_text(8, 38, "stale", (220, 220, 230));
        font.draw_text(80, 38, digit(stale), tint);
        font.draw_text(8, 50, "fresh", (220, 220, 230));
        font.draw_text(80, 50, digit(fresh), tint);
        font.draw_text(8, 70, verdict, tint);
        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
    }
}

//! `hello-input` -- poll the port-1 pad every frame and
//! paint the screen with feedback that reacts to the user's input.
//!
//! Proves two pipelines end-to-end:
//! 1. SIO0 + pad (keyboard event → winit → emulator bus → SIO0 pad
//!    → homebrew poll).
//! 2. `psx-font`: ASCII text rendering through a 4bpp CLUT atlas
//!    in VRAM. The label row at the top spells out every held button
//!    so the visual matches whatever we polled.
//!
//! Bindings (mapped by the frontend's keyboard handler):
//! - D-pad UP    → brighten red channel
//! - D-pad DOWN  → brighten green channel
//! - D-pad LEFT  → brighten blue channel
//! - D-pad RIGHT → reset to black
//! - CROSS / CIRCLE / TRIANGLE / SQUARE draw a small coloured
//!   triangle in the centre whose orientation rotates with the
//!   face-button pressed.
//! - The program asks for analog mode at boot and locks it
//!   (`require_analog_on`, see `sdk/docs/PAD-ANALOG.md`), so the
//!   DualShock Analog button (F9 on the frontend keyboard, or gamepad
//!   Mode/Guide when the OS exposes it) no longer switches it back.
//!   A pad plugged in later is asked again. In analog mode the
//!   bottom-left status panel shows raw stick bytes. Keyboard
//!   defaults: arrow keys for left stick, I/J/K/L for right stick.

#![no_std]
#![no_main]

extern crate psx_rt;

use psx_font::{fonts::BASIC, FontAtlas};
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::prim::TriFlat;
use psx_gpu::Gpu;
use psx_pad::{button, require_analog_on, ButtonState, PadMode, PadReader, PadState, Port};
use psx_vram::{Clut, TextureDepth, TexturePage};

/// Font atlas VRAM slot.
///
/// With double-buffering, buffer A is at (0..320, 0..240) and B
/// at (0..320, 240..480). TexturePage X must be a multiple of 64 → 320
/// is the lowest slot that clears both buffers. At 4bpp, a BASIC
/// 128-glyph atlas uses 64 halfwords × 32 halfword rows →
/// (320..384) × (0..32), inside tpage (320, 0, Bit4).
const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
/// 2-entry CLUT (transparent + white) at (320, 256). X is a
/// multiple of 16 ✓, past the right edge of buffer B at X=320 ✓.
const FONT_CLUT: Clut = Clut::new(320, 256);

#[no_mangle]
fn main() {
    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));

    // One-shot: expand the 1bpp BASIC font into a 4bpp CLUT texture
    // + a tiny transparent/white CLUT, both parked off the
    // framebuffer.
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);

    let mut r: u8 = 0;
    let mut g: u8 = 0;
    let mut b: u8 = 32;

    // A program started by a launcher inherits whatever mode the last one
    // left, so it asks for analog and the lock itself. The reader keeps the
    // last clean state through a poll the driver had to reject.
    let mut port = peripherals.controller_port;
    let _ = require_analog_on(&mut port, Port::One);
    let mut reader = PadReader::port1();
    let mut was_connected = true;

    loop {
        let state = reader.poll_on(&mut port);
        // A pad plugged in later starts in digital mode, and one parked in
        // configuration mode (ID 0xF3) never reaches analog by itself: ask
        // again for both, not every frame for a digital-only pad (the
        // request blocks for a few frames).
        if (state.is_connected() && !was_connected) || state.mode == PadMode::Config {
            let _ = require_analog_on(&mut port, Port::One);
        }
        was_connected = state.is_connected();
        let pad = state.buttons;

        // Direction buttons nudge the background color.
        if pad.is_held(button::UP) {
            r = r.saturating_add(4);
        }
        if pad.is_held(button::DOWN) {
            g = g.saturating_add(4);
        }
        if pad.is_held(button::LEFT) {
            b = b.saturating_add(4);
        }
        if pad.is_held(button::RIGHT) {
            r = 0;
            g = 0;
            b = 32;
        }

        // Background -- clear the back buffer.
        fb.clear(&mut gpu, (r, g, b));

        // Face buttons paint a coloured triangle in the centre of
        // the screen. Each direction rotates 90° so "Triangle"
        // literally points up, etc.
        face_button_tri(&mut gpu, pad);

        // Label row: show every held button as its uppercase name.
        // `(0x80, 0x80, 0x80)` = unmodulated white (PSX texture tint
        // is `output = texel * tint / 128`).
        draw_button_labels(&font, pad);
        draw_pad_status(&font, state);

        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
    }
}

/// Paint the name of every held button down the top-left of the
/// screen. One line per button -- 8 px tall, so 14 buttons fits
/// comfortably inside 240 px of vertical room with a 2px gap.
fn draw_button_labels(font: &FontAtlas, pad: ButtonState) {
    // Header, unconditional -- sanity check that the font is alive
    // even when no key is pressed.
    font.draw_text(4, 4, "HELD:", (0x80, 0x80, 0x80));

    // (button mask, label, tint) -- tints match the triangle colours
    // where applicable so the label lines up visually with the
    // on-screen primitive.
    let rows: &[(u16, &str, (u8, u8, u8))] = &[
        (button::UP, "UP", (0xC0, 0x30, 0x30)),
        (button::DOWN, "DOWN", (0x30, 0xC0, 0x30)),
        (button::LEFT, "LEFT", (0x30, 0x30, 0xC0)),
        (button::RIGHT, "RIGHT", (0xA0, 0xA0, 0xA0)),
        (button::TRIANGLE, "TRIANGLE", (0x30, 0xC0, 0x30)),
        (button::CIRCLE, "CIRCLE", (0xC0, 0x30, 0x30)),
        (button::CROSS, "CROSS", (0x30, 0x80, 0xC0)),
        (button::SQUARE, "SQUARE", (0xC0, 0x30, 0xC0)),
        (button::L1, "L1", (0xA0, 0xA0, 0x30)),
        (button::R1, "R1", (0xA0, 0xA0, 0x30)),
        (button::L2, "L2", (0x60, 0xA0, 0x60)),
        (button::R2, "R2", (0x60, 0xA0, 0x60)),
        (button::L3, "L3", (0x60, 0xC0, 0xC0)),
        (button::R3, "R3", (0x60, 0xC0, 0xC0)),
        (button::START, "START", (0xE0, 0xE0, 0xE0)),
        (button::SELECT, "SELECT", (0xE0, 0xE0, 0xE0)),
    ];

    // Label area: start at y=16 (below the HELD: header), advance 10
    // px per line (8 px glyph + 2 px gap). Skip unpressed rows.
    let mut y: i16 = 16;
    for &(mask, label, tint) in rows {
        if pad.is_held(mask) {
            font.draw_text(4, y, label, tint);
            y = y.wrapping_add(10);
        }
    }

    // Bottom-right: show the raw bitmask in hex so the parity tests
    // can latch onto something stable regardless of which buttons
    // were held.
    let hex = hex_u16(pad.bits());
    font.draw_text(320 - 8 * 6 - 4, 240 - 10, &hex, (0x70, 0x70, 0x70));
}

fn draw_pad_status(font: &FontAtlas, state: PadState) {
    let (mode, tint) = match state.mode {
        PadMode::Disconnected => ("NO PAD", (0xE0, 0x50, 0x50)),
        PadMode::Digital => ("DIGITAL", (0xE0, 0x90, 0x40)),
        PadMode::Analog => ("ANALOG", (0x60, 0xE0, 0x80)),
        PadMode::Config => ("CONFIG", (0x90, 0xA0, 0xE0)),
        PadMode::Unknown => ("UNKNOWN", (0xE0, 0xE0, 0x60)),
    };

    font.draw_text(4, 188, "MODE:", (0x80, 0x80, 0x80));
    font.draw_text(52, 188, mode, tint);

    let id = hex_u8(state.id_low);
    font.draw_text(124, 188, "ID:", (0x60, 0x60, 0x60));
    font.draw_text(152, 188, &id, (0x70, 0x70, 0x70));

    font.draw_text(4, 200, "ANALOG:", (0x80, 0x80, 0x80));
    if state.is_analog() {
        font.draw_text(68, 200, "ON", (0x60, 0xE0, 0x80));
        let lx = hex_u8(state.sticks.left_x);
        let ly = hex_u8(state.sticks.left_y);
        let rx = hex_u8(state.sticks.right_x);
        let ry = hex_u8(state.sticks.right_y);
        font.draw_text(4, 212, "L:", (0x80, 0x80, 0x80));
        font.draw_text(28, 212, &lx, (0x70, 0xC0, 0xE0));
        font.draw_text(68, 212, &ly, (0x70, 0xC0, 0xE0));
        font.draw_text(4, 224, "R:", (0x80, 0x80, 0x80));
        font.draw_text(28, 224, &rx, (0xC0, 0x90, 0xE0));
        font.draw_text(68, 224, &ry, (0xC0, 0x90, 0xE0));
    } else if state.is_connected() {
        font.draw_text(68, 200, "OFF", (0xE0, 0x90, 0x40));
        font.draw_text(4, 212, "PRESS ANALOG BUTTON", (0x90, 0x90, 0x90));
    } else {
        font.draw_text(68, 200, "N/A", (0xE0, 0x50, 0x50));
        font.draw_text(4, 212, "CONNECT A CONTROLLER", (0xE0, 0x90, 0x40));
    }
}

/// `0x1234` as a 6-char string -- `'0'`, `'x'`, then 4 uppercase hex
/// digits, written into a stack buffer. no_std-friendly (no alloc).
fn hex_u16(v: u16) -> HexU16 {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = [0u8; 6];
    out[0] = b'0';
    out[1] = b'x';
    out[2] = HEX[((v >> 12) & 0xF) as usize];
    out[3] = HEX[((v >> 8) & 0xF) as usize];
    out[4] = HEX[((v >> 4) & 0xF) as usize];
    out[5] = HEX[(v & 0xF) as usize];
    HexU16(out)
}

/// `0x12` as a 4-char string.
fn hex_u8(v: u8) -> HexU8 {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = [0u8; 4];
    out[0] = b'0';
    out[1] = b'x';
    out[2] = HEX[((v >> 4) & 0xF) as usize];
    out[3] = HEX[(v & 0xF) as usize];
    HexU8(out)
}

/// Owning newtype around a 4-byte hex buffer.
struct HexU8([u8; 4]);
impl HexU8 {
    fn as_str(&self) -> &str {
        // SAFETY: only ASCII hex digits + '0', 'x' are ever written
        // to the buffer.
        unsafe { core::str::from_utf8_unchecked(&self.0) }
    }
}
impl core::ops::Deref for HexU8 {
    type Target = str;
    fn deref(&self) -> &str {
        self.as_str()
    }
}

/// Owning newtype around a 6-byte hex buffer so `as_str` borrows
/// from `self` -- avoids dangling-slice pitfalls with stack arrays.
struct HexU16([u8; 6]);
impl HexU16 {
    fn as_str(&self) -> &str {
        // SAFETY: only ASCII hex digits + '0', 'x' are ever written
        // to the buffer.
        unsafe { core::str::from_utf8_unchecked(&self.0) }
    }
}
impl core::ops::Deref for HexU16 {
    type Target = str;
    fn deref(&self) -> &str {
        self.as_str()
    }
}

fn face_button_tri(gpu: &mut Gpu, pad: ButtonState) {
    let (verts, color) = if pad.is_held(button::TRIANGLE) {
        (
            [(160, 100), (140, 140), (180, 140)],
            (80, 220, 80), // green
        )
    } else if pad.is_held(button::CIRCLE) {
        (
            [(180, 120), (140, 100), (140, 140)],
            (220, 80, 80), // red
        )
    } else if pad.is_held(button::CROSS) {
        (
            [(160, 140), (140, 100), (180, 100)],
            (80, 160, 220), // blue
        )
    } else if pad.is_held(button::SQUARE) {
        (
            [(140, 120), (180, 100), (180, 140)],
            (220, 80, 220), // magenta
        )
    } else {
        // No face button held: tiny white triangle so the app still
        // shows signs of life.
        ([(160, 118), (156, 124), (164, 124)], (200, 200, 200))
    };
    gpu.draw(&TriFlat::new(verts, color.0, color.1, color.2));
}

